parameters.jsCode:
// Consolida las opiniones de la noticia en un texto para que la IA las sintetice.
const opiniones = $input.all().map((o) => o.json);

const textoOpiniones = opiniones
  .map((o, i) => `Opinión ${i + 1} (voto: ${o.sentiment}): ${o.texto}`)
  .join("\n\n");

return [
  {
    json: {
      noticia_id: opiniones[0]?.noticia_id ?? "",
      total: opiniones.length,
      texto_opiniones: textoOpiniones,
    },
  },
];

